commandActions.command:
Add-Type -AssemblyName System.IO.Compression.FileSystem
$files = @('3.6. Oferte\1. Suntree Solar Tech SRL\Solicitare oferta Suntree Solar Tech SRL.docx','3.2. Decizie Alegere Furnizor\Nota justificativa alegere furnizor.docx','3.4. Contract de achizitie bunuri si servici\Contract Suntree Solar Tech SRL - Cesiro Production SRL.docx')
foreach ($f in $files) { Write-Output "DOCUMENT: $f"; $z=[IO.Compression.ZipFile]::OpenRead((Join-Path (Get-Location) $f)); $r=[IO.StreamReader]::new($z.GetEntry('word/document.xml').Open()); [xml]$x=$r.ReadToEnd(); $r.Close(); $z.Dispose(); $n=[Xml.XmlNamespaceManager]::new($x.NameTable); $n.AddNamespace('w','http://schemas.openxmlformats.org/wordprocessingml/2006/main'); $x.SelectNodes('//w:p',$n) | ForEach-Object { ($_.SelectNodes('.//w:t',$n) | ForEach-Object { $_.InnerText }) -join '' } }
